mappings.INQUIRY.response:
status = 201 or status = 200
  ? (body.status = "CREATED" and $type(body.sessionId) = "string" and body.sessionId != ""
      and $type(body.hostedPageUrl) = "string" and body.hostedPageUrl != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.sessionId,
         "attributes": {"sessionId": body.sessionId, "hostedPageUrl": body.hostedPageUrl}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 400 or status = 422) and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.PAY.response:
status = 201 or status = 200
  ? (body.status = "CAPTURED" and $type(body.paymentId) = "string" and body.paymentId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.paymentId, "code": body.code,
         "attributes": {"amount": body.amount, "currency": body.currency,
                        "clientReference": body.clientReference}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 400 or status = 422) and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.status = "CAPTURED" and $type(body.paymentId) = "string" and body.paymentId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.paymentId, "code": body.code,
         "attributes": {"amount": body.amount, "currency": body.currency,
                        "clientReference": body.clientReference}}
      : body.status = "DECLINED" and $type(body.code) = "string" and body.code != ""
        ? {"outcome": "FAILED", "code": body.code, "message": body.message}
      : body.status = "PENDING"
        ? {"outcome": "PENDING", "partnerRef": body.paymentId}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 201 or status = 200
  ? (body.status = "REFUNDED" and $type(body.refundId) = "string" and body.refundId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.refundId, "code": body.code}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 404 or status = 422) and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.CALLBACK.response:
$type(body.clientReference) != "string" or body.clientReference = ""
  or $type(body.sessionId) != "string" or body.sessionId = "" ? {}
: body.status = "AUTHENTICATED" and $type(body.transientToken) = "string" and body.transientToken != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.sessionId, "reference": body.clientReference,
     "code": body.code,
     "attributes": {"sessionId": body.sessionId, "transientToken": body.transientToken}}
: body.status = "FAILED" and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "partnerRef": body.sessionId, "reference": body.clientReference,
     "code": body.code, "message": body.message, "attributes": {"sessionId": body.sessionId}}
: {}
